-- ==========================================================================
-- B3 RECUT, INTERMEDIATE TIER: Terminals, Depots & Fuel Supply (supply)
-- question text brought to petrolord-engines e972ae7 (engines PR #232).
--
-- WHY. Engines #232 recasts engine sentences that broke the owner copy rule
-- (contrastives such as "X, not Y" and "rather than") and gives the queue
-- its facility vocabularies (a CNG forecourt now speaks of dispensers). It
-- moves no value. This LIVE bank quoted the old sentences verbatim, so the
-- quotes are brought to the engine's words. Text only.
--
-- WHAT MOVES. 3 of the 132 questions of this tier, 0 with a changed keyed
-- answer TEXT and 0 with a changed answer INDEX. No ord, no module key, no
-- scope, no option order and no row count moves, so every question id and
-- every learner attempt against it survives.
-- Fields rewritten: 2 explanation, 1 options.
-- Rows (scope, module_key, ord):
--   module m04-throughput-economics ord 7: options
--   module m05-the-lane-the-fleet-and-the-station ord 5: explanation
--   final - ord 37: explanation
--
-- GUARDS. Each row is addressed by its stable identity (app_slug, tier, scope,
-- module_key, ord) and must match EITHER its published text exactly, in which
-- case it is updated, OR the recut text exactly, in which case it is already
-- applied and left alone. Anything else raises and the transaction rolls back.
-- Every update asserts it touched exactly 1 row, and the tier must still hold
-- 132 questions at the end.
--
-- The published strings are the rows migrations/20261012_tds_supply_intermediate_deep.sql wrote
-- (APPLIED 2026-09-19), regenerated byte for byte from the banks before this
-- recut. The recut strings are the recut banks. Written by
-- docs/b3-engine-strings-recut/gen_recut.py; see RECUT-supply.json.
--
-- SAFE TO RE-RUN. A second run finds every row already carrying the recut
-- text and updates nothing.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
begin

  -- module m04-throughput-economics ord 7: options
  select case
           when prompt = 'Density is missing from the IBAFO period. Which note explains the gap in the carbon columns?' and options = '["No emission factor supplied, so the carbon side is not computed. Factors are published, versioned data; an invented one would be worse than none.", "No diesel emission factor supplied, so the carbon figure is absent rather than zero.", "No product density supplied, so the loss has no weight and the carbon side is not computed.", "REFUSED: Density is required to convert between mass and volume; it is not assumed."]'::jsonb and answer_index = 2 and explanation = 'throughputEconomics does not refuse the call; it prints the money side and names why the carbon side is missing. The refusal about mass and volume belongs to cargoQuantities, and the diesel note to the truck lane.' then 'old'
           when prompt = 'Density is missing from the IBAFO period. Which note explains the gap in the carbon columns?' and options = '["No emission factor supplied, so the carbon side is not computed. Factors are published, versioned data; an invented one would be worse than none.", "No diesel emission factor supplied, so the carbon figure is left blank.", "No product density supplied, so the loss has no weight and the carbon side is not computed.", "REFUSED: Density is required to convert between mass and volume; it is not assumed."]'::jsonb and answer_index = 2 and explanation = 'throughputEconomics does not refuse the call; it prints the money side and names why the carbon side is missing. The refusal about mass and volume belongs to cargoQuantities, and the diesel note to the truck lane.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'supply' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm04-throughput-economics'::text and ord = 7;
  if v_state is null then raise exception 'B3 recut supply intermediate refused: no row for module m04-throughput-economics ord 7'; end if;
  if v_state = 'other' then raise exception 'B3 recut supply intermediate refused: module m04-throughput-economics ord 7 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'Density is missing from the IBAFO period. Which note explains the gap in the carbon columns?', options = '["No emission factor supplied, so the carbon side is not computed. Factors are published, versioned data; an invented one would be worse than none.", "No diesel emission factor supplied, so the carbon figure is left blank.", "No product density supplied, so the loss has no weight and the carbon side is not computed.", "REFUSED: Density is required to convert between mass and volume; it is not assumed."]'::jsonb, answer_index = 2, explanation = 'throughputEconomics does not refuse the call; it prints the money side and names why the carbon side is missing. The refusal about mass and volume belongs to cargoQuantities, and the diesel note to the truck lane.'
     where app_slug = 'supply' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm04-throughput-economics'::text and ord = 7;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B3 recut supply intermediate refused: module m04-throughput-economics ord 7 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- module m05-the-lane-the-fleet-and-the-station ord 5: explanation
  select case
           when prompt = 'The IBAFO lane reports 224.64 diesel litres a trip. What does it print for kg CO2e a trip?' and options = '["0, since a missing factor is read as a zero emission.", "A figure from the synthetic 850 kg CO2e a tonne factor.", "none, with a note that no diesel emission factor was supplied.", "A refusal, with the lane left uncosted until a factor is typed."]'::jsonb and answer_index = 2 and explanation = 'The engine ships no factor, so the diesel volume is computed and its emissions wait for a factor with a source. In the engine''s words the carbon figure "is absent rather than zero". The rest of the lane still prints complete true.' then 'old'
           when prompt = 'The IBAFO lane reports 224.64 diesel litres a trip. What does it print for kg CO2e a trip?' and options = '["0, since a missing factor is read as a zero emission.", "A figure from the synthetic 850 kg CO2e a tonne factor.", "none, with a note that no diesel emission factor was supplied.", "A refusal, with the lane left uncosted until a factor is typed."]'::jsonb and answer_index = 2 and explanation = 'The engine ships no factor, so the diesel volume is computed and its emissions wait for a factor with a source. In the engine''s words the carbon figure "is left blank". The rest of the lane still prints complete true.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'supply' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm05-the-lane-the-fleet-and-the-station'::text and ord = 5;
  if v_state is null then raise exception 'B3 recut supply intermediate refused: no row for module m05-the-lane-the-fleet-and-the-station ord 5'; end if;
  if v_state = 'other' then raise exception 'B3 recut supply intermediate refused: module m05-the-lane-the-fleet-and-the-station ord 5 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'The IBAFO lane reports 224.64 diesel litres a trip. What does it print for kg CO2e a trip?', options = '["0, since a missing factor is read as a zero emission.", "A figure from the synthetic 850 kg CO2e a tonne factor.", "none, with a note that no diesel emission factor was supplied.", "A refusal, with the lane left uncosted until a factor is typed."]'::jsonb, answer_index = 2, explanation = 'The engine ships no factor, so the diesel volume is computed and its emissions wait for a factor with a source. In the engine''s words the carbon figure "is left blank". The rest of the lane still prints complete true.'
     where app_slug = 'supply' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm05-the-lane-the-fleet-and-the-station'::text and ord = 5;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B3 recut supply intermediate refused: module m05-the-lane-the-fleet-and-the-station ord 5 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- final final ord 37: explanation
  select case
           when prompt = 'Which two notes say a carbon figure is absent because no emission factor was supplied?' and options = '["The depot''s no-density note and the lane''s diesel note, both about factors.", "The depot''s no-density note and assumedZero.", "The depot''s no-emission-factor note and the lane''s diesel note.", "The lane''s floor and the station''s warning."]'::jsonb and answer_index = 2 and explanation = 'throughputEconomics: "No emission factor supplied, so the carbon side is not computed." truckingEconomics: "No diesel emission factor supplied, so the carbon figure is absent rather than zero." The no-density note is about the loss''s weight.' then 'old'
           when prompt = 'Which two notes say a carbon figure is absent because no emission factor was supplied?' and options = '["The depot''s no-density note and the lane''s diesel note, both about factors.", "The depot''s no-density note and assumedZero.", "The depot''s no-emission-factor note and the lane''s diesel note.", "The lane''s floor and the station''s warning."]'::jsonb and answer_index = 2 and explanation = 'throughputEconomics: "No emission factor supplied, so the carbon side is not computed." truckingEconomics: "No diesel emission factor supplied, so the carbon figure is left blank." The no-density note is about the loss''s weight.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'supply' and tier = 'intermediate' and scope = 'final' and module_key is not distinct from null::text and ord = 37;
  if v_state is null then raise exception 'B3 recut supply intermediate refused: no row for final final ord 37'; end if;
  if v_state = 'other' then raise exception 'B3 recut supply intermediate refused: final final ord 37 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'Which two notes say a carbon figure is absent because no emission factor was supplied?', options = '["The depot''s no-density note and the lane''s diesel note, both about factors.", "The depot''s no-density note and assumedZero.", "The depot''s no-emission-factor note and the lane''s diesel note.", "The lane''s floor and the station''s warning."]'::jsonb, answer_index = 2, explanation = 'throughputEconomics: "No emission factor supplied, so the carbon side is not computed." truckingEconomics: "No diesel emission factor supplied, so the carbon figure is left blank." The no-density note is about the loss''s weight.'
     where app_slug = 'supply' and tier = 'intermediate' and scope = 'final' and module_key is not distinct from null::text and ord = 37;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B3 recut supply intermediate refused: final final ord 37 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_count from public.academy_quiz_questions where app_slug = 'supply' and tier = 'intermediate';
  if v_count <> 132 then raise exception 'B3 recut supply intermediate refused: supply intermediate holds % questions, expected 132', v_count; end if;
  raise notice 'B3 recut supply intermediate: % of 3 rows updated, % already recut', v_updated, 3 - v_updated;
end
$$;
